import{_ as d,o as r,c as a,a3 as e}from"./chunks/framework.CqzWVxDX.js";const c=JSON.parse('{"title":"Modbus TCP / RTU 协议介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/modbus/index.md","filePath":"guide/protocols/modbus/index.md","lastUpdated":1786981506000}'),o={name:"guide/protocols/modbus/index.md"};function s(n,t,l,i,h,b){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="modbus-tcp-rtu-协议介绍" tabindex="-1">Modbus TCP / RTU 协议介绍 <a class="header-anchor" href="#modbus-tcp-rtu-协议介绍" aria-label="Permalink to &quot;Modbus TCP / RTU 协议介绍&quot;">​</a></h1><h2 id="协议概述" tabindex="-1">协议概述 <a class="header-anchor" href="#协议概述" aria-label="Permalink to &quot;协议概述&quot;">​</a></h2><p>Modbus 由 Modicon（现 Schneider Electric）于 1979 年发布，是<strong>工业自动化领域应用最广泛的通信协议</strong>。它采用简单的主从（Master/Slave）请求-响应模型，广泛用于 PLC、RTU、传感器、变频器等设备的互联。</p><p>EMS Simulate 基于 <code>pymodbus</code> 库实现 Modbus 协议，支持 <strong>Modbus TCP</strong>（以太网）与 <strong>Modbus RTU</strong>（RS-232/RS-485 串口）两种常见变体，可配置为服务端（模拟从站）或客户端（作为主站读取真实设备）。</p><h2 id="支持的模式" tabindex="-1">支持的模式 <a class="header-anchor" href="#支持的模式" aria-label="Permalink to &quot;支持的模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>物理介质</th><th>特点</th></tr></thead><tbody><tr><td><strong>Modbus TCP</strong></td><td>以太网</td><td>基于 TCP 502 端口，帧 = MBAP 头 + PDU，无需校验码</td></tr><tr><td><strong>Modbus RTU</strong></td><td>RS-232 / RS-485</td><td>基于串口，帧 = 地址 + 功能码 + 数据 + CRC16 校验，报文间需 ≥3.5 字符间隔</td></tr></tbody></table><blockquote><p>Modbus ASCII 变体暂不支持。</p></blockquote><h2 id="数据模型-四类数据区" tabindex="-1">数据模型（四类数据区） <a class="header-anchor" href="#数据模型-四类数据区" aria-label="Permalink to &quot;数据模型（四类数据区）&quot;">​</a></h2><p>Modbus 以&quot;数据区 + 地址&quot;寻址，共四类数据区：</p><table tabindex="0"><thead><tr><th>数据区</th><th>地址范围</th><th>读写属性</th><th>典型用途</th></tr></thead><tbody><tr><td>线圈（Coil）</td><td>0xxxx</td><td>可读可写</td><td>开关量输出（继电器等）</td></tr><tr><td>离散输入（Discrete Input）</td><td>1xxxx</td><td>只读</td><td>开关量输入（按钮、限位等）</td></tr><tr><td>保持寄存器（Holding Register）</td><td>4xxxx</td><td>可读可写</td><td>参数、设定值（16 位）</td></tr><tr><td>输入寄存器（Input Register）</td><td>3xxxx</td><td>只读</td><td>采集量（16 位）</td></tr></tbody></table><p>每个寄存器为 16 位，多个寄存器可组合表示 32 位整数或 IEEE 754 浮点数（由<strong>解析码</strong>决定解释方式）。</p><h2 id="支持的功能码" tabindex="-1">支持的功能码 <a class="header-anchor" href="#支持的功能码" aria-label="Permalink to &quot;支持的功能码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能码</th><th>名称</th><th>操作对象</th></tr></thead><tbody><tr><td>01</td><td>读线圈</td><td>线圈</td></tr><tr><td>02</td><td>读离散输入</td><td>离散输入</td></tr><tr><td>03</td><td>读保持寄存器</td><td>保持寄存器</td></tr><tr><td>04</td><td>读输入寄存器</td><td>输入寄存器</td></tr><tr><td>05</td><td>写单个线圈</td><td>线圈</td></tr><tr><td>06</td><td>写单个寄存器</td><td>保持寄存器</td></tr><tr><td>15</td><td>写多个线圈</td><td>线圈</td></tr><tr><td>16</td><td>写多个寄存器</td><td>保持寄存器</td></tr></tbody></table><h2 id="解析码系统" tabindex="-1">解析码系统 <a class="header-anchor" href="#解析码系统" aria-label="Permalink to &quot;解析码系统&quot;">​</a></h2><p>不同厂商设备的寄存器字节序各异，EMS Simulate 内置 <strong>27 种解析码</strong>，覆盖常见的数据格式：</p><ul><li><strong>8 位</strong>：Byte（无符号 / 有符号）；</li><li><strong>16 位</strong>：Short AB（大端）、Short BA（字节交换）、Short CD（小端），各有符号/无符号；</li><li><strong>32 位整数</strong>：Long AB CD（大端）、Long BA DC（大端字交换）、Long DC BA（小端）、Long CD AB（小端字交换），各有符号/无符号；</li><li><strong>32 位浮点</strong>：Float AB CD、Float BA DC、Float CD AB（对应不同字节序）；</li><li><strong>64 位</strong>：Int64、Double（大端 / 小端）。</li></ul><p>配合<strong>乘法系数</strong>与<strong>加法系数</strong>可将原始值换算为工程值：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真实值 = 寄存器原始值 × 乘法系数 + 加法系数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="角色说明" tabindex="-1">角色说明 <a class="header-anchor" href="#角色说明" aria-label="Permalink to &quot;角色说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>行为</th></tr></thead><tbody><tr><td><strong>服务端（Server / 从站）</strong></td><td>软件监听端口（TCP）或串口，维护四类数据区内容，响应主站的读/写请求</td></tr><tr><td><strong>客户端（Client / 主站）</strong></td><td>软件主动发起请求，读取或写入真实从站的数据</td></tr></tbody></table><h2 id="常用术语" tabindex="-1">常用术语 <a class="header-anchor" href="#常用术语" aria-label="Permalink to &quot;常用术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>从站地址（Slave ID / Unit ID）</td><td>RTU 中为 1~247，TCP 中为单元标识符</td></tr><tr><td>PDU</td><td>协议数据单元（功能码 + 数据）</td></tr><tr><td>事务标识符</td><td>TCP 帧中用于匹配请求与响应的编号</td></tr><tr><td>解析码（Decode Code）</td><td>决定寄存器原始值如何解释为数值</td></tr></tbody></table><blockquote><p>📄 详细操作见 <a href="./operation.html">Modbus 操作指南</a>，报文结构见 <a href="./packet-view.html">Modbus 报文查看</a>。</p></blockquote>',23)])])}const p=d(o,[["render",s]]);export{c as __pageData,p as default};
